import{_ as i,o as n,c as t,a3 as l}from"./chunks/framework.B9qR_F1m.js";const c=JSON.parse('{"title":"Versionen","description":"","frontmatter":{},"headers":[],"relativePath":"referenz/versionen.md","filePath":"referenz/versionen.md"}'),a={name:"referenz/versionen.md"};function r(s,e,u,o,d,h){return n(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="versionen" tabindex="-1">Versionen <a class="header-anchor" href="#versionen" aria-label="Permalink to &quot;Versionen&quot;">​</a></h1><p>Die Desktop-App aktualisiert sich selbst. Alle Downloads: <a href="https://github.com/Leichtester/shardwing-releases/releases" target="_blank" rel="noreferrer">Releases</a>.</p><h2 id="_0-5-10-·-05-11-2026" tabindex="-1">0.5.10 · 05.11.2026 <a class="header-anchor" href="#_0-5-10-·-05-11-2026" aria-label="Permalink to &quot;0.5.10 · 05.11.2026&quot;">​</a></h2><p><strong>Zusammen mit dem Mission Editor</strong></p><ul><li>Die Desktop-App lädt die offene Mission von selbst neu, sobald du sie im DCS Mission Editor speicherst. Deine ungespeicherten Änderungen bleiben erhalten, bei gleichen Stellen gilt der ME (<a href="/dcs/speichern#zusammen-mit-dem-mission-editor">mehr</a>)</li><li>Verwirft der ME die Shardwing-Planungsdaten, schreibt Shardwing sie beim nächsten Speichern wieder hinein</li></ul><p><strong>Flights anlegen</strong></p><ul><li>Auch auf einer Seite ohne Einheiten: Shardwing bietet CJTF Blue/USA bzw. CJTF Red/Russia an und legt das Land beim Speichern mit an</li></ul><h2 id="_0-5-9-·-05-11-2026" tabindex="-1">0.5.9 · 05.11.2026 <a class="header-anchor" href="#_0-5-9-·-05-11-2026" aria-label="Permalink to &quot;0.5.9 · 05.11.2026&quot;">​</a></h2><p><strong>Flights anlegen</strong></p><ul><li>Neue F-16C- und F/A-18C-Flights direkt in Shardwing: Anzahl, Spieler oder KI, Aufgabe, Callsign und Start</li><li>Tanker und AWACS anlegen: Typ, Seite, Start in der Luft, von der Startbahn oder kalt bzw. heiß vom Parkplatz, mit Callsign, Frequenz und TACAN; danach gleich den Track zeichnen</li><li>Flights duplizieren und entfernen (Flight-Kopf)</li><li>Startart und Parkplatz pro Maschine über der Route, automatisch nebeneinander oder per Klick</li><li>Parkplätze farbig auf der Karte, mit Popup zu Größe und Belegung</li></ul><p><strong>Timing</strong></p><ul><li>Fenster in Minuten statt Sekunden, auch auf den Kneeboards</li><li>Bei „+ Sollzeit“ direkt einen Planungspunkt wählen; ohne Punkt bleibt es eine normale Sollzeit</li></ul><p><strong>Karte</strong></p><ul><li><kbd>Esc</kbd> schließt Popups und lässt die Auswahl los; auf der Flight-Seite bleibt der Flight gewählt</li></ul><h2 id="_0-5-8-·-03-11-2026" tabindex="-1">0.5.8 · 03.11.2026 <a class="header-anchor" href="#_0-5-8-·-03-11-2026" aria-label="Permalink to &quot;0.5.8 · 03.11.2026&quot;">​</a></h2><p><strong>Funk</strong></p><ul><li>Gruppenfrequenz jedes Flights unter Units &amp; Funk einstellen (nur Designer), wird beim Speichern in die Mission geschrieben</li><li>Hinweis bei doppelter Frequenz, Frequenz außerhalb des Rasters oder auf einem Netz des Comm Plans</li><li>Frequenzen verteilen: jeder Spieler-Flight bekommt eine eigene freie Frequenz</li></ul><p><strong>Tanker und AWACS</strong></p><ul><li>KI-Skript zum Einschalten: bei Bingo über die Exit-Route heim statt quer durchs Gebiet</li><li>Ablösung durch eine zweite Gruppe mit Late Activation, Startzeit wird ausgerechnet</li></ul><h2 id="_0-5-7-·-03-11-2026" tabindex="-1">0.5.7 · 03.11.2026 <a class="header-anchor" href="#_0-5-7-·-03-11-2026" aria-label="Permalink to &quot;0.5.7 · 03.11.2026&quot;">​</a></h2><p><strong>Tanker</strong></p><ul><li>Track mit Inbound-Kurs und Leg-Länge einstellen, der Anfang des Tracks bleibt liegen</li><li>ARIP-Linie entfällt in allen Tanker-Tracks</li></ul><p><strong>Planungspunkte</strong></p><ul><li>Punkt sitzt genau auf der Koordinate und bleibt beim Zoomen dort</li><li>AR-Punkt lässt sich mit dem Track eines Tankers verbinden und wandert mit</li><li>Orte ohne Zeit: erscheinen nur in der DTC, nicht in Sollzeiten und Prüfungen</li><li>Timing-Gantt zeigt Sollzeiten und Planungspunkte als Rauten</li></ul><h2 id="_0-5-6-·-02-11-2026" tabindex="-1">0.5.6 · 02.11.2026 <a class="header-anchor" href="#_0-5-6-·-02-11-2026" aria-label="Permalink to &quot;0.5.6 · 02.11.2026&quot;">​</a></h2><p><strong>Treffpunkte</strong></p><ul><li>Planungspunkte (RV, Marshal, Holding, CP, IP, Push, Fence, AR) in den Zeichnungen setzen; ein Flight sieht nur die Punkte, an denen er eingetragen ist</li><li>Mehrere Flights an einem Punkt mit eigener Zeit und eigenem Höhenband; Zeiten staffeln, Bänder stapeln, Warnung bei Überlappung</li><li>Holding-Punkte zeichnen ein HOLD-Muster für alle Flights, auf der Karte und im F10</li><li>„Übertragen auf …“: Auftrag, Push, Sollzeiten, Höhenblock, AAR und Notiz auf andere Flights kopieren, mit Zeit- und Höhenschritt</li><li>TOS-Rechner zeigt das Höhenband und setzt die Routenhöhe des Steerpoints auf die Unterkante</li><li>Sollzeiten im Timing übersichtlicher, jede als eigene Karte</li></ul><p><strong>Tanker und AWACS</strong></p><ul><li>Auftrag für KI-Tanker und -AWACS: Callsign, Funk und TACAN, Vorschlag für den Comm Plan</li><li>Track zeichnen (Race-Track oder Kreis, Seite tauschen), wird als Orbit in die Route geschrieben</li><li>Entry- und Exit-Route um den Track, Landeplatz wählbar, Hinweis bei SAM-Ringen</li><li>Zeitplan mit On und Off Track; Shardwing rechnet die nötige Startzeit vor</li><li>Tanker-Track als Treffpunkt im TOS-Rechner</li><li>KI-Flights zeigen DTC, Angriff und Lineup Card nur noch, wo es Sinn ergibt</li></ul><p><strong>Sonst</strong></p><ul><li>Karte mit W, A, S, D verschieben, mit Shift schneller</li><li>Lineup Card: leere 9-Line-Seite (CAS Brief)</li><li>Beladung: CBU-103 und CBU-105 mit Canister-Symbol</li></ul><h2 id="_0-5-5-·-02-11-2026" tabindex="-1">0.5.5 · 02.11.2026 <a class="header-anchor" href="#_0-5-5-·-02-11-2026" aria-label="Permalink to &quot;0.5.5 · 02.11.2026&quot;">​</a></h2><ul><li>Neuer Startbildschirm mit „Beispiel ansehen“: öffnet die Demo-Mission „Operation Desert Veil“</li><li>Startbildschirm zeigt zuletzt geöffnete Missionen und was neu ist</li><li>Handbuch jetzt unter handbuch.shardwing.de</li></ul><h2 id="_0-5-4-·-02-11-2026" tabindex="-1">0.5.4 · 02.11.2026 <a class="header-anchor" href="#_0-5-4-·-02-11-2026" aria-label="Permalink to &quot;0.5.4 · 02.11.2026&quot;">​</a></h2><ul><li>Übersicht: Halten am Push-Punkt zählt mit, keine falsche Meldung „Push laut Route“ mehr</li><li>Handbuch: neue Bilder mit der Demo-Mission „Operation Desert Veil“, Checklisten für Designer, Flight Lead und Wingman</li></ul><h2 id="_0-5-3-·-02-11-2026" tabindex="-1">0.5.3 · 02.11.2026 <a class="header-anchor" href="#_0-5-3-·-02-11-2026" aria-label="Permalink to &quot;0.5.3 · 02.11.2026&quot;">​</a></h2><p><strong>Timing</strong></p><ul><li>Startzeit der Mission änderbar (Designer), wird in die .miz geschrieben</li><li>Gantt: gezogene Kanten haften dezent an Wegpunkten, H und anderen Fenstern (Alt schaltet ab)</li><li>Sollzeiten mit optionalem Ort: der Flight setzt seinen Steerpoint beim Zuordnen dorthin</li><li>AAR-Slots im TOS-Rechner als Info, zählen nur mit Zuordnung</li><li>DEAD auch als TOT statt Fenster</li><li>TOS-Rechner: GS-Spalte richtig ausgerichtet</li></ul><h2 id="_0-5-2-·-02-11-2026" tabindex="-1">0.5.2 · 02.11.2026 <a class="header-anchor" href="#_0-5-2-·-02-11-2026" aria-label="Permalink to &quot;0.5.2 · 02.11.2026&quot;">​</a></h2><p><strong>Timing</strong></p><ul><li>Weitere Sollzeiten pro Flight (z. B. RV, IP) ohne festen Wegpunkt; Zeiten auch als Uhrzeit eingeben</li><li>TOS-Rechner in der DTC (NAV): Sollzeiten Steerpoints zuordnen, eigene Zeiten und Halten, TOS auf Knopfdruck übernehmen</li><li>TOS aus der Cartridge bleiben bei Client-Slots stehen (Wegpunkt-Tabelle im Timing zeigt sie jetzt)</li></ul><p><strong>IADS und Server</strong></p><ul><li>Netz-Ansicht ordnet die Symbole wie auf der Karte, verrutscht beim Verbinden nicht mehr; „Nach Ebenen“ als Alternative</li><li>Warnung „Nicht gespeichert: Das IADS hat … Fehler“ verschwindet nach 20 s</li><li>Server-Verwaltung unter <code>#/admin</code>, Missionen löschen und automatischer Ablauf</li></ul><h2 id="_0-5-1-·-01-11-2026" tabindex="-1">0.5.1 · 01.11.2026 <a class="header-anchor" href="#_0-5-1-·-01-11-2026" aria-label="Permalink to &quot;0.5.1 · 01.11.2026&quot;">​</a></h2><p><strong>Rechtliches</strong></p><ul><li>Impressum, Datenschutz und Lizenzen in der App (Menü, Startseite, Anmeldeseite)</li><li>Kneeboard-Karten auf OpenStreetMap-Grundkarte, Satellitenkarte entfernt</li><li>MOOSE-Lizenz liegt mit dem IADS in der Mission</li><li>Hinweis beim Teilen: nur hochladen, was du teilen darfst</li></ul><h2 id="_0-5-0-·-01-11-2026" tabindex="-1">0.5.0 · 01.11.2026 <a class="header-anchor" href="#_0-5-0-·-01-11-2026" aria-label="Permalink to &quot;0.5.0 · 01.11.2026&quot;">​</a></h2><p><strong>IADS-Werkzeug</strong></p><ul><li>SAM-Übersicht: alle Luftabwehr-Gruppen mit Filtern und Hinweisen, Benennen nach Konvention in einem Rutsch</li><li>Netz-Editor mit Daten-, Strom- und Schutz-Verbindungen, Was-wäre-wenn</li><li>Export ins Mission Script: MOOSE, EMCON, IADS und Netz-Datei per MISSION-START-Trigger</li><li>Warnung bei fremden IADS-Skripten</li></ul><h2 id="_0-4-0-·-31-10-2026" tabindex="-1">0.4.0 · 31.10.2026 <a class="header-anchor" href="#_0-4-0-·-31-10-2026" aria-label="Permalink to &quot;0.4.0 · 31.10.2026&quot;">​</a></h2><p><strong>Attack Planner</strong></p><ul><li>Direct, Indirect, Wheel, Toss, Standoff und Standoff mit Pull-up</li><li>Profil und Draufsicht, Attack Card fürs Kneeboard</li></ul><h2 id="_0-3-0-·-31-10-2026" tabindex="-1">0.3.0 · 31.10.2026 <a class="header-anchor" href="#_0-3-0-·-31-10-2026" aria-label="Permalink to &quot;0.3.0 · 31.10.2026&quot;">​</a></h2><p><strong>Kneeboards aufgeräumt</strong></p><ul><li>Cockpit-Satz aus Lineup Card, Comm Card und Route</li><li>Comm Card mit Netz-Farben, Diverts, Index mit Seitenzahlen, Nachtmodus, vorbelegte Vorlagen</li><li>Kneeboards und Paketinfos ohne KI-Flights</li></ul><h2 id="_0-2-1-·-31-10-2026" tabindex="-1">0.2.1 · 31.10.2026 <a class="header-anchor" href="#_0-2-1-·-31-10-2026" aria-label="Permalink to &quot;0.2.1 · 31.10.2026&quot;">​</a></h2><ul><li>Timing: Client-Slots starten zum nötigen Zeitpunkt, Hinweis bei Vul deutlich zu früh</li></ul><h2 id="_0-2-0-·-31-10-2026" tabindex="-1">0.2.0 · 31.10.2026 <a class="header-anchor" href="#_0-2-0-·-31-10-2026" aria-label="Permalink to &quot;0.2.0 · 31.10.2026&quot;">​</a></h2><ul><li>Timing als Gantt mit Rollen-Gruppen, Rückwärtsplanung bis zum Anlassen, Sonnenzeiten, Zoom</li><li>Tanker-Slots (AAR) und entschärfte Deconfliction</li><li>Wegpunkt-Tabelle mit TOS, Wegpunkte in Tabellen bearbeiten</li><li>Rückgängig/Wiederherstellen für jede Änderung</li><li>Callsign-Vorschläge nach Rolle</li><li>Panel auf ganze Höhe (<kbd>⌘⇧↵</kbd>)</li></ul><h2 id="_0-1-6-–-0-1-7-·-29-10-2026" tabindex="-1">0.1.6 – 0.1.7 · 29.10.2026 <a class="header-anchor" href="#_0-1-6-–-0-1-7-·-29-10-2026" aria-label="Permalink to &quot;0.1.6 – 0.1.7 · 29.10.2026&quot;">​</a></h2><ul><li>Beladung: Stationsleiste, Bearbeiten, Freigabe für Piloten</li><li>Eigene Kräfte als NATO-Symbole</li><li>Geteilte Cartridge: ein Flight kann sich eine eigene Kopie anlegen</li></ul><h2 id="_0-1-5-·-29-10-2026" tabindex="-1">0.1.5 · 29.10.2026 <a class="header-anchor" href="#_0-1-5-·-29-10-2026" aria-label="Permalink to &quot;0.1.5 · 29.10.2026&quot;">​</a></h2><ul><li>Zeichnungen: Schalter „Alle Einheiten zeigen“</li><li>Timing: Steerpoints der DTC-Routen 2 und 3 als Push- und Zielpunkt</li><li>Comm Card übernimmt die DTC-Kanäle</li><li>Kartenausschnitt: Vorschau groß, Stellungen pro Ausschnitt ausblendbar</li></ul><h2 id="_0-1-4-·-28-10-2026" tabindex="-1">0.1.4 · 28.10.2026 <a class="header-anchor" href="#_0-1-4-·-28-10-2026" aria-label="Permalink to &quot;0.1.4 · 28.10.2026&quot;">​</a></h2><ul><li>Routen von KI-Flights direkt auf der Karte bearbeiten</li><li>Timing, Deconfliction und Lagekarte nutzen die Route der Cartridge</li><li>Comm Plan: Frequenzen vorschlagen</li><li>Paketübersicht mit Auswahl, Threat-Positionen in jedem Koordinatenformat</li></ul><h2 id="_0-1-2-·-28-10-2026" tabindex="-1">0.1.2 · 28.10.2026 <a class="header-anchor" href="#_0-1-2-·-28-10-2026" aria-label="Permalink to &quot;0.1.2 · 28.10.2026&quot;">​</a></h2><ul><li>Timing mit Sync-Matrix: H-Hour, TOT/Vul/SEAD-Fenster, Push, Deconfliction</li><li>Comm Plan mit Comm Card</li><li>Eigene Callsigns und Aufgaben</li><li>Wetter: METAR je Flugplatz</li><li>Messwerkzeug (Taste M), Zuletzt geöffnet</li></ul><h2 id="_0-1-1-·-28-10-2026" tabindex="-1">0.1.1 · 28.10.2026 <a class="header-anchor" href="#_0-1-1-·-28-10-2026" aria-label="Permalink to &quot;0.1.1 · 28.10.2026&quot;">​</a></h2><ul><li>Kartenausschnitte: eigene Kartenseiten, gedreht, mit Ebenen und Gitter</li><li>Flugplätze und Bodenstationen aller DCS-Karten</li><li>Lagekarte, Bullseye versetzen</li></ul><h2 id="_0-1-0-·-27-10-2026" tabindex="-1">0.1.0 · 27.10.2026 <a class="header-anchor" href="#_0-1-0-·-27-10-2026" aria-label="Permalink to &quot;0.1.0 · 27.10.2026&quot;">​</a></h2><p>Erste Version mit automatischen Updates: Missionen und Cartridges öffnen, bearbeiten und am Ort speichern; gemeinsam planen über den Shardwing-Server.</p>',71)])])}const m=i(a,[["render",r]]);export{c as __pageData,m as default};
